      const a = lin(o.grad[0]), b = lin(o.grad[1]);
      U.uToonGradA = { value: new T.Vector3(a.r, a.g, a.b) };
      U.uToonGradB = { value: new T.Vector3(b.r, b.g, b.b) };
      U.uToonGradY = { value: new T.Vector2(o.grad[2] || 0, o.grad[3] === undefined ? 2 : o.grad[3]) };
