    const S = 2.5, cw = Math.ceil(w / S), ch = Math.ceil(h / S), wS = cw * S, hS = ch * S; // wS / hS：遮罩实际盖住的范围（贴图坐标按它算，不按 w / h）
    const c = makeCanvas(cw, ch), g = c.getContext('2d'), im = g.createImageData(cw, ch), d = im.data;
