  const ashSpireGeo = () => geo('ashSpire', () => toonGradient(spireGeo().clone(), { bottom: ASH_PAL.rockLo, top: 0xffffff, y0: 0, y1: 2.4 }));
  function ashRockMat() {
    return own(makeToonMat({ color: ASH_PAL.rock, brush: 0.16, brushScale: 0.42, soft: 0.1 }));
  }
