    const bk = h4 + Math.PI, rd = ashRay(AR, AR.core.x, AR.core.z, bk) + 2.5;
    const door = { x: AR.core.x + Math.sin(bk) * rd, z: AR.core.z + Math.cos(bk) * rd };
