      walls.push([ax, az, bx, bz]);
      const p = { t: 'rbox', x: (ax + bx) / 2, z: (az + bz) / 2, hx: th / 2, hz: l / 2 + th / 2, ang, round: 0.12 };
      S.cuts.push({ prim: p, mat: MAT.WALL });
