      if (d < R3.core.r + 1.5 || nearDoor(x, z, 5) || axisD(R3.id, x, z) < 3.4) continue;
      const tg = a + Math.PI / 2 * (r() < 0.5 ? 1 : -1);
      if (!tryL(x, z, tg, rnd(3.6, 5.2), a + Math.PI, rnd(1.8, 2.6))) continue;
      const cang = Math.atan2(Math.sin(tg), Math.cos(tg));
