        parts.push([ashSlabGeo(), bx - vx * f.w * 0.42, 0.45, bz - vz * f.w * 0.42, 0, f.ang + r(-0.1, 0.1), 0, 0.8, 0.95, 0.8, 0.78]);
        const sl = r(1.6, 2.4);
