      const prims = arena ? [{ t: 'circle', x: I.x, z: I.z, r: FROST.arenaR + 0.8 }] : isle(I.x, I.z, I.rad, 3 + (R() < 0.5 ? 1 : 0), i === 1 ? 0.9 : rnd(0.72, 0.84));
