          const q0 = i > 0 ? hw * Math.tan(Math.abs(turn(i)) / 2) + 0.15 : 0, q1 = i + 2 < P.length ? hw * Math.tan(Math.abs(turn(i + 1)) / 2) + 0.15 : 0;
