    // 脚下再贴碎石 / 覆盖斑（buildDecals 的 clusters）。只在路外（sd ≤ -0.3）放，碰撞照旧来自地形；随机数走自己的一路（ashRng），原有岩石的摆放不变
    const clusters = [], rockIM = { A: null, B: null };
    const clusterRocks = () => {
      const tc0 = performance.now();
      const cr = ashRng(zone, 12), q = (a, b) => a + (b - a) * cr();
      const src = ash ? rocksA.slice() : rocksA.concat(rocksB);
      for (let i = 0; i < src.length; i += 10) {
        const x = src[i], z = src[i + 2], sx = src[i + 6];
        if (sx < 1.4) continue;
        clusters.push([x, z, sx]);
        // 一两块中石（贴着大石、偏开一个方向）+ 三四块碎石散在外圈
        const nm = cr() < 0.5 ? 2 : 1, a0 = q(0, TAU);
        for (let k = 0; k < nm; k++) {
          const a = a0 + (k ? q(1.6, 2.6) : 0) + q(-0.3, 0.3), d = sx * q(0.95, 1.25), px = x + Math.sin(a) * d, pz = z + Math.cos(a) * d, s2 = sx * q(0.4, 0.55);
          if (sd(px, pz) > -0.6 || (ash ? ashNoRock(zone, px, pz, s2) : !edgeOk(px, pz))) continue;
          const sy = s2 * q(0.7, 1.0);
          (ash ? rocksA : rocksB).push(px, sy * 0.28, pz, q(-0.3, 0.3), q(0, TAU), q(-0.3, 0.3), s2 * q(0.9, 1.15), sy, s2 * q(0.9, 1.15), q(0.5, 0.7));
        }
        const n = cr() < 0.5 ? 4 : 3;
        for (let k = 0; k < n; k++) {
          const a = q(0, TAU), d = sx * q(1.1, 1.7), px = x + Math.sin(a) * d, pz = z + Math.cos(a) * d, s2 = q(0.24, 0.45);
          if (sd(px, pz) > -0.3 || (ash ? ashNoRock(zone, px, pz, s2) : !edgeOk(px, pz))) continue;
          const sy = s2 * q(0.6, 0.95);
          rocksB.push(px, sy * 0.28, pz, q(-0.3, 0.3), q(0, TAU), q(-0.3, 0.3), s2 * q(0.85, 1.2), sy, s2 * q(0.85, 1.2), q(0.6, 0.86));
        }
      }
      vfMs.cl = +(performance.now() - tc0).toFixed(2);
    };
    if (!ash) {
      ringSamples(1.2, 0.72, (x, z) => {
        if (sd(x, z) > -0.5) return;
        pushRock(x + rand(-0.2, 0.2), z + rand(-0.2, 0.2), rand(0.5, 0.85), 1);
      });
      ringSamples(1.9, 2.2, (x, z) => {
        if (sd(x, z) > -1.75) return;
        const lk = lowK(x, z);
        if (Math.random() < 0.28) {
          const s = rand(0.8, 1.3);
          pushSpire([x, -0.2, z, rand(-0.18, 0.18), rand(0, TAU), rand(-0.18, 0.18), s, s * rand(0.9, 1.6) * lk, s, rand(0.6, 1.0)]);
        } else pushRock(x + rand(-0.4, 0.4), z + rand(-0.4, 0.4), rand(1.0, 1.65), rand(1, 1.35) * (lk < 1 ? 0.75 : 1));
      });
      ringSamples(4.2, 4.6, (x, z) => {
        x += rand(-1.2, 1.2);
        z += rand(-1.2, 1.2);
        if (sd(x, z) > -3.6 || Math.random() < 0.3) return;
        const s = rand(1.2, 2.0);
        pushSpire([x, -0.3, z, rand(-0.22, 0.22), rand(0, TAU), rand(-0.22, 0.22), s, s * rand(0.9, 1.6) * lowK(x, z), s, rand(0.4, 0.75)]);
      });
    }

    // 第 0 区：卡通岩石（纯色 + 笔触 + 竖向渐变，不用照片贴图），程序化外观和 PBR 外观都一样
    let rockMat = ash
      ? ashRockMat()
      : hd
        ? triMaterial(gx, { con: 1, nrm: 1, sat: 1, rough: 0.92, cap: true })
        : own(new T.MeshStandardMaterial({ color: 0xffffff, roughness: 0.96, metalness: 0, flatShading: true }));
    const rockTint = ash ? new T.Color(1, 1, 1) : lin(def.rock);
    if (!ash && RK.toon) {
      // 卡通岩石（纯色 + 笔触 + 竖向渐变）：实例色照旧是 def.rock × 明暗，材质底色 = top / def.rock（线性空间逐通道），低画质再压一档（没有贴地薄雾）
      const tc = RK.toon, rT = lin(tc.top), rD = lin(def.rock), rK = qualId === 'low' ? tc.kLow || 0.7 : tc.k || 0.88;
      rockMat = own(makeToonMat({ vertexColors: false, flat: true, brush: 0.14, brushScale: 0.5, grad: [tc.bot, 0xffffff, -0.3, 2.4] }));
      rockMat.color.setRGB((rK * rT.r) / Math.max(1e-3, rD.r), (rK * rT.g) / Math.max(1e-3, rD.g), (rK * rT.b) / Math.max(1e-3, rD.b));
    }
    if (ash) {
      // 同一种几何体换几个变体（每个变体一个实例化网格），不至于所有石头一个样
      const split = (list, n) => {
        const out = [];
        for (let k = 0; k < n; k++) out.push([]);
        for (let i = 0; i < list.length; i += 10) out[(i / 10) % n].push(...list.slice(i, i + 10));
        return out;
      };
      // zones-ash：每种大小只留一个变体（原来各 2 个）：省 4 次 draw（实例化网格不做视锥剔除，投影再画一遍），石头靠缩放和朝向就够不一样了
      split(rocksA, ASH_ROCK.variants).forEach((l, k) => (rockIM.A = instanced(ashRockGeo(k), rockMat, l, true, rockTint)));
      split(rocksB, ASH_ROCK.variants).forEach((l, k) => (rockIM.B = instanced(ashRockGeo(2 + k), rockMat, l, true, rockTint)));
      instanced(ashSpireGeo(), rockMat, spires, true, rockTint);
    } else {
      rockIM.A = instanced(rockGeoA(), rockMat, rocksA, true, rockTint);
      rockIM.B = instanced(rockGeoB(), rockMat, rocksB, true, rockTint);
      instanced(spireGeo(), rockMat, spires, true, rockTint);
    }

    vfMs.rocks = +(performance.now() - vfMs.t0).toFixed(2); // 建外观开始到岩石摆完（调试）
    vrSection(5); // 外观随机序列按段重新起头（见 withVisualRandom）
    // --- 主题摆件（有 CC0 布景模型时只保留 keep 比例的程序化摆件，其余换成模型，见 buildProps） ---
    const props = [];
    const withProps = hd && propsReady(gx);
    const keepK = withProps ? gx.props.keep : 1;
    ringSamples(6.5, 4.2, (x, z) => {
      x += rand(-1.5, 1.5);
      z += rand(-1.5, 1.5);
      if (sd(x, z) > -3.0 || Math.random() < 0.3 || Math.random() >= keepK) return;
      const s = rand(0.85, 1.6);
      const v = [x, -0.1, z, rand(-0.1, 0.1), rand(0, TAU), rand(-0.1, 0.1), s, s * rand(0.9, 1.3) * (lowK(x, z) < 1 ? 0.65 : 1), s, 1];
      if (edgeOk(x, z)) props.push(...v);
    });
    const icy = def.id === 'frost', rift = def.id === 'rift';
    const propMat = own(
      new T.MeshStandardMaterial({
        vertexColors: true, flatShading: true, roughness: icy ? 0.25 : rift ? 0.35 : 0.9, metalness: icy || rift ? 0.1 : 0,
        emissive: lin(def.accent), emissiveIntensity: icy ? 0.22 : rift ? 0.2 : def.id === 'abyss' ? 0.1 : 0,
      })
    );
    instanced(propGeo(def.id), propMat, props, true, null);

    vrSection(6); // 外观随机序列按段重新起头（见 withVisualRandom）
    // --- 发光水晶簇 + 地面光晕 ---
    const crystals = [], glows = [];
    ringSamples(8.5, 1.6, (x, z) => {
      if (sd(x, z) > -1.1 || Math.random() < 0.3) return;
      const ok = edgeOk(x, z), c0 = crystals.length, g0 = glows.length;
      const h = rand(0.9, 1.6);
      crystals.push(x, h * 0.45, z, rand(-0.25, 0.25), rand(0, TAU), rand(-0.25, 0.25), 0.26, h, 0.26, 1);
      const n = G.randInt(1, 3);
      for (let k = 0; k < n; k++) {
        const a = rand(0, TAU), hh = h * rand(0.4, 0.7);
        crystals.push(x + Math.sin(a) * 0.4, hh * 0.4, z + Math.cos(a) * 0.4, Math.cos(a) * 0.5, rand(0, TAU), -Math.sin(a) * 0.5, 0.18, hh, 0.18, 1);
      }
      const gr = rand(2.6, 3.8);
      glows.push(x, 0.05, z, 0, 0, 0, gr, 1, gr, 1);
      if (!ok) {
        crystals.length = c0;
        glows.length = g0;
      }
    });
    const accentL = lin(def.accent);
    const crystalMat = own(
      new T.MeshStandardMaterial({ color: accentL.clone().multiplyScalar(0.3), emissive: accentL, emissiveIntensity: 1.0, roughness: 0.3, flatShading: true, toneMapped: false })
    );
    instanced(gOct(1), crystalMat, crystals, false, null); // 发光的水晶不投影（zones-polish：影子看不出来，每区省一次阴影 draw；第 0 区原来就在 dress 里关掉了）
    const glowMat = own(
      new T.MeshBasicMaterial({ map: glowTex(), color: accentL, transparent: true, opacity: 0.4, blending: T.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    // 每区的水晶旋钮 ZONE_GFX.<id>.crystal = { col 发光色, k 发光强度, base 底色（缺省 col × 0.3）, glow 地面光晕色, glowK }（zones-integrate）
    const CR = gx && gx.crystal;
    if (CR) {
      crystalMat.emissive.copy(lin(CR.col)).multiplyScalar(CR.k !== undefined ? CR.k : 1);
      crystalMat.color.copy(CR.base !== undefined ? lin(CR.base) : lin(CR.col).multiplyScalar(0.3));
      glowMat.color.copy(lin(CR.glow !== undefined ? CR.glow : CR.col)).multiplyScalar(CR.glowK !== undefined ? CR.glowK : 1);
    }
    const glowIM = instanced(gQuad(), glowMat, glows, false, null);
    if (glowIM) glowIM.renderOrder = 1;

    vrSection(7); // 外观随机序列按段重新起头（见 withVisualRandom）
    // --- 地面暗斑 ---
    // 每区可以在 ZONE_GFX.<id>.blots = { k: 块数倍率（默认 1）, r: 大小倍率（默认 1）, op: 不透明度（默认 0.2）, show: 贴花层里只画的比例（缺省全画）, tex: 'crack' } 调污斑（zones-ash 加的旋钮）。
    // zones-polish：tex: 'crack' 把软边的暗块换成细裂纹（groundCrackTex），读起来是地面的纹路而不是脏印子
    const BL = Object.assign({ k: 1, r: 1, op: 0.2 }, gx && gx.blots);
    const blots = [];
    const blot = (x, z, r) => {
      if (BL.k >= 1 || Math.random() < BL.k) blots.push(x, 0.02, z, 0, rand(0, TAU), 0, r * BL.r, 1, r * BL.r * rand(0.6, 1), 1);
    };
    // 每个房间按内切圆撒 6 块；带 axis 的通道房间沿中线撒 2 块
    for (const rm of zone.rooms) {
      if (rm.axis) {
        const A = rm.axis;
        for (let k = 0; k < 2; k++) {
          const t = rand(0.3, 0.7), q = axisAt(A, t);
          blot(q.x + rand(-1, 1), q.z + rand(-1, 1), rand(1.4, 2.6));
        }
        continue;
      }
      const c = rm.core;
      for (let k = 0; k < 6; k++) {
        const a = rand(0, TAU), d = Math.sqrt(Math.random()) * Math.max(0.5, c.r - 2.5);
        blot(c.x + Math.sin(a) * d, c.z + Math.cos(a) * d, rand(1.6, 4.2));
      }
    }
    const blotMat = own(
      // 卡通：污斑不再是近黑的一大片（旧 0.38 不透明度把地面弄脏），颜色偏向这个区域的阴影色、淡一半
      new T.MeshBasicMaterial({ map: BL.tex === 'crack' ? groundCrackTex() : blotchTex(), color: lin(ash ? 0x2a1c1a : mixHex(mixHex(def.voidc, toonLightOf(def).shade, 0.3), 0x000000, 0.3)), transparent: true, opacity: BL.op, depthWrite: false }) // 第 0 区：暖的焦黑，不是冷紫
    );
    if (decalQ) {
      // vf-ground：污斑并进贴花层（同样的位置、大小、颜色和不透明度，图集里的裂纹 / 水渍格），省掉这一次 draw
      for (let i = 0; i < blots.length; i += 10) {
        const bx = blots[i], bz = blots[i + 2];
        if (LY && coverW(bx, bz, sd(bx, bz), trailK(bx, bz, sd(bx, bz))) > 0.45) continue; // 盖着积层的地方不画裂纹（像树根）
        if (BL.show !== undefined && ((i / 10) * 0.6180339887) % 1 >= BL.show) continue; // tex-t1：show = 只画这么大比例（按序号的黄金分割序列挑，不取随机数）
        decalPush(bx, bz, blots[i + 6], blots[i + 8], blots[i + 4], BL.tex === 'crack' ? DECAL_CELL.crack : DECAL_CELL.stain, blotMat.color, BL.op);
      }
      vfBurnMesh(blots);
    } else {
      const blotIM = instanced(gQuad(), blotMat, blots, false, null);
      if (blotIM) blotIM.renderOrder = 1;
    }

    vrSection(8); // 外观随机序列按段重新起头（见 withVisualRandom）
    // --- 法阵：首领竞技场（主题色）和起点（淡色） ---
    const sigil = (x, z, r, hex, op) => {
      const m = own(
        new T.MeshBasicMaterial({ map: sigilTex(), color: lin(hex), transparent: true, opacity: op, blending: T.AdditiveBlending, depthWrite: false, toneMapped: false })
      );
      const q = new T.Mesh(gQuad(), m);
      q.position.set(x, 0.03, z);
      q.scale.set(r, 1, r);
      q.renderOrder = 1;
      zoneGroup.add(q);
      return q;
    };
    // 每区的法阵旋钮 ZONE_GFX.<id>.sigil = { r（× bossR，缺省 0.84）, op（基准不透明度，缺省 0.24，每帧在这上下呼吸）,
    //   col（缺省区域强调色）, dark（往黑里混的比例）, k（线性空间的亮度倍率）, start（false = 不要起点的小法阵）}；sigil: null = 不画首领法阵。
    // zones-integrate：原来 frost / rift / abyss 在 dress 里按贴图和位置找到法阵再改，storm 想改改不了
    const SG = gx && 'sigil' in gx ? gx.sigil : {};
    let bossSigil = null, startSigil = null;
    if (SG) {
      bossSigil = sigil(zone.bossPos.x, zone.bossPos.z, zone.bossR * (SG.r || 0.84), SG.dark ? mixHex(SG.col || def.accent, 0x000000, SG.dark) : SG.col || def.accent, SG.op || 0.24);
      if (SG.k !== undefined) bossSigil.material.color.multiplyScalar(SG.k);
      bossSigil.userData.op = SG.op || 0.24;
    }
    // 起点的法阵：镜头拉近后原来的 3.4 会铺满半个画面，收成脚下一小圈、更淡（布景工作可以整个换掉）
    // 第 0 区不要起点法阵（贴在地上像界面，和布景不是一体的）；起点的布景见 buildAshDress
    if (!SG || SG.start !== false) startSigil = sigil(zone.start.x, zone.start.z, 1.9, mixHex(def.sky, 0xffffff, 0.3), 0.1);
    const dress = ash ? buildAshDress(zone, sd) : null;
    const ashGlow = ashFisPending ? ashFisPending.glow.slice() : []; // vf-ground：起点余烬裂缝的位置（光池用；之后会被区域布景拼进熔岩网格）
    const rp = rift ? riftPieces(zone, sd, ringSamples, lowK, accentL, crystalMat) : null;
    vrSection(9); // 外观随机序列按段重新起头（见 withVisualRandom）
    // --- CC0 布景模型、火盆、贴地薄雾 ---
    let fires = null, mist = null;
    if (hd) {
      if (withProps) {
        const pm = triMaterial(gx, { vc: true, con: 0.5, nrm: 0.6, sat: gx.prop.sat, tint: gx.prop.tint, tintK: 1.0, rough: 0.86 });
        fires = buildProps(zone, gx, sd, ringSamples, lowK, { rock: rockMat, prop: pm, edgeOk });
      }
      if (gx.mist) mist = buildMist(zone, gx, sd);
      prefetchNext(def);
    }
    if (gx && !withProps) requestZoneAssets(zone, gx);

    vrSection(10); // 外观随机序列按段重新起头（见 withVisualRandom）
    // 各区自己的布景（B 阶段在 ZONE_TERRAIN[id].dress 里写）
    const TZ = terrainOf(def);
    const tctx = terrainCtx(zone, { sd, lowK, hd, gx, fires: fires ? fires.list : null, rock: rockMat, rockTint, prop: propMat, crystal: crystalMat, glow: glowMat, blot: blotMat, ground, voidMesh, bossSigil, startSigil });
    const tstate = TZ.dress ? TZ.dress(zone, tctx) : null;
    // vf-ground：暖色光池（火盆 + 余烬裂缝 + 熔岩），烘进地面顶点色。和贴花一起放到进区之后的空档里做（不算进建区耗时）
    const vfJobs = [];
    // ① 地面顶点按 vf-ground 的各层重算（颜色按比例乘，各区布景改过的权重不动）
    // 顶点按网格下标（vid）逐个重算：先按 main 的算法再算一遍（hdV null），和 LY 的结果比，颜色按比例乘，权重没被布景改过才换
    if (LY && hd) vfJobs.push(() => {
      const tv0 = performance.now(), g = ground.geometry, P = g.attributes.position.array, Cc = g.attributes.color, Aw = g.attributes.aW, Ac = g.attributes.aC;
      if (!Cc || !Aw || !Ac) return;
      const C = Cc.array, W2 = Aw.array, A1 = Ac.array;
      for (let k = 0; k < vid.length; k++) {
        const vi = vid[k];
        if (vi < 0) continue;
        const x = x0 + (k % sx) * CS, z = z0 + Math.floor(k / sx) * CS, d = sdv[k];
        if (Math.abs(P[vi * 3] - x) > 1e-3 || Math.abs(P[vi * 3 + 2] - z) > 1e-3) continue; // 被布景挪过的顶点（深渊崖边）不动
        const n = 0.84 + 0.3 * vnoise(x * 0.09 + 7.3, z * 0.09 - 2.1);
        const ao = ash ? 0.42 + 0.58 * smooth01((d + 0.3) / 3.6) : 0.5 + 0.5 * smooth01(d / 2.6);
        let kk = d >= 0 ? 1 : smooth01(1 + d / SKIRT);
        kk *= kk;
        const tk = trailK(x, z, d), lit = n * ao * (1 + 0.2 * tk), pn = vnoise(x * 0.17 + 11.3, z * 0.17 - 5.1);
        hdV(x, z, d, tk, pn, lit, kk, null, hv0);
        hdV(x, z, d, tk, pn, lit, kk, LY, hv);
        for (let c = 0; c < 3; c++) C[vi * 3 + c] *= hv[c] / Math.max(1e-5, hv0[c]);
        if (Math.abs(W2[vi * 2] - hv0[3]) < 1e-5 && Math.abs(W2[vi * 2 + 1] - hv0[4]) < 1e-5) {
          W2[vi * 2] = hv[3];
          W2[vi * 2 + 1] = hv[4];
        }
        A1[vi] = hv[5];
      }
      Cc.needsUpdate = Aw.needsUpdate = Ac.needsUpdate = true;
      vfMs.verts = +(performance.now() - tv0).toFixed(2);
    });
    // ② 成簇的岩石：算出伴生的中石 / 碎石，换上更大的实例化网格（同一个几何体和材质，draw 不变）
    if (decalQ) vfJobs.push(() => {
      const tc0 = performance.now(), nA = rocksA.length, nB = rocksB.length;
      vfIso(() => {
        clusterRocks();
        const swap = (old, list, n0) => {
          if (!old || list.length === n0) return;
          const im = instanced(old.geometry, old.material, list, true, rockTint);
          if (!im) return;
          im.userData.cs0 = true;
          im.castShadow = qualId !== 'low';
          zoneGroup.remove(old);
          old.dispose();
        };
        swap(rockIM.A, rocksA, nA);
        swap(rockIM.B, rocksB, nB);
      });
      vfMs.cl = +(performance.now() - tc0).toFixed(2);
    });
    if (hd && gx.pool) vfJobs.push(() => {
      const pts = [];
      if (fires) for (const f of fires.list) pts.push(f.x, f.z, 2.4, 1);
      for (let i = 0; i < ashGlow.length; i += 10) pts.push(ashGlow[i], ashGlow[i + 2], ashGlow[i + 6] * 1.1, 0.8);
      if (gx.pool.glows) for (let i = 0; i < glows.length; i += 10) pts.push(glows[i], glows[i + 2], glows[i + 6] * 0.9, 0.7); // 晶簇脚下的光晕
      const P4 = [];
      for (let i = 0; i < pts.length; i += 4) P4.push(pts.slice(i, i + 4));
      const tp0 = performance.now();
      lightPools(zone, ground, gx, P4);
      vfMs.pools = +(performance.now() - tp0).toFixed(2);
    });
    // vf-ground：贴花层（接触阴影要等各区布景都摆好，所以放在最后），整区一张网格
    if (decalQ) {
      const dm = vfIso(() => decalMesh(DECAL_EMPTY)), q0 = decalQ;
      zoneGroup.add(dm);
      const dctx = { trail: ashT, clusters, cover: LY ? (x, z) => { const d = sd(x, z); return coverW(x, z, d, trailK(x, z, d)); } : null };
      vfJobs.push(() => {
        const t0 = performance.now();
        decalQ = q0;
        try {
          buildDecals(zone, gx, sd, dctx);
          const t1 = performance.now();
          vfIso(() => decalFill(dm, decalQ));
          vfMs = Object.assign(vfMs, { decals: +(t1 - t0).toFixed(2), mesh: +(performance.now() - t1).toFixed(2), n: decalQ.length / 11 });
        } finally {
          decalQ = null;
        }
      });
    }
    decalQ = null;
    if (vfJobs.length) {
      const zg = zoneGroup;
      setTimeout(() => {
        if (zoneGroup !== zg || W.zone !== zone) return; // 已经换区 / 重建了
        // 远处实例的剔除（icull）可能已经在这之前的某一帧里按镜头挤掉了实例：先全部复原，接触阴影贴花按完整的实例摆；
        // 跑完再让 icull 重新登记（成簇岩石换上的新网格也要剔除）。不然结果取决于这个 setTimeout 和第一帧谁先到
        if (icull && icull.group === zg) for (const e of icull.list) if (!e.off) icullRestore(e);
        icull = null;
        for (const f of vfJobs) f();
        icull = null;
        // 马上按镜头焦点重新登记、剔除（模拟暂停时 W.update 不跑，不能等下一帧）；镜头还没跟过来（换区后还没 update 过）就按它马上要到的位置
        const P = G.player;
        if (camSnap) icullUpdate(P.x, P.z + CAM_LEAD);
        else icullUpdate(camT.x, camT.z + CAM_LEAD);
      }, 0);
    }

    _c.set(gx && gx.amb !== undefined ? gx.amb : def.accent); // 环境火星的颜色：ZONE_GFX.<id>.amb（缺省区域强调色，zones-integrate）
    const chests = buildChests(zone);
    // vf-vfx3：区域氛围的 Points（种子用自己的序列，不动全局随机数）
    let amb = null;
    {
      let h = 2166136261;
      for (const ch of def.id) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
      let a = h >>> 0 || 1;
      amb = buildAmbience(def.id, () => ((a = (a * 16807) % 2147483647) / 2147483647));
      if (amb) {
        own(amb.g);
        own(amb.mat);
        amb.pts.visible = qualId !== 'low' && ambOn();
        zoneGroup.add(amb.pts);
      }
    }
    zoneFx = {
      amb,
      terrain: tstate, tctx, tz: TZ, chests,
      st, crystalMat, glowMat, bossSigil,
      ar: _c.r, ag: _c.g, ab: _c.b,
      ambAcc: 0, boltIn: rand(3, 7), boltT: 0,
      isles: rp ? rp.isles : null, skyMat: rp ? rp.skyMat : null, starIn: rand(1.5, 4),
      fires, mist, gU: hd ? gmat.userData.U : null, hd, props: withProps, dress, layer: !!LY,
      retier: zoneRetier, // tex-t2：换画质档换完纹理图像以后调（见 swapZoneTex）
    };
