  const HP_COL = [['head', 0, 1.79, 0.0, 0.15], ['chest', 0, 1.58, -0.03, 0.2], ['chest', 0, 1.4, -0.01, 0.235]];
  const SF_COL = [['head', 0, 1.79, 0.0, 0.16], ['chest', 0, 1.4, 0.0, 0.225], ['spine', 0, 1.2, 0.0, 0.195], ['root', 0, 0.95, 0.0, 0.215]];
