          const fl = Math.sin(t * (10.5 + i * 1.7) + i * 1.2 + side * 0.9 + ph), fz = Math.sin(t * (8.3 + i * 1.3) + i * 1.5 + side * 2.1 + ph);
          const idle = Math.sin(t * 1.6 + i * 0.8 + side * 0.6 + ph) * 0.06 * (1 - r1);
