          'uaL.rx': [0, -0.5, 1, -1.0], 'uaL.rz': [0, -0.1, 1, -0.6], 'faL.rx': [0, -0.7, 1, -1.7],
          'uaR.rx': [0, -0.5, 1, -1.0], 'uaR.rz': [0, 0.1, 1, 0.6], 'faR.rx': [0, -0.7, 1, -1.7],
