          'handL.oy': [0, 0, 1, 2.1], 'handL.ox': [0, 0, 1, 0.5], 'handL.rx': [0, -0.15, 1, -0.6],
          'handR.oy': [0, 0, 1, 2.1], 'handR.ox': [0, 0, 1, -0.5], 'handR.rx': [0, -0.15, 1, -0.6],
