        'root.oz': [0, 0, 0.3, -0.06, -0.45, 0.16, 0.72, 0.13, 1, 0],
        'chest.ry': [0, -0.1, 0.3, -0.45, -0.45, 0.45, 0.72, 0.38, 1, -0.1],
