  // 命中点的一记四芒星闪光
  function flare(x, y, z, hex, size, dur) {
    // vf-vfx2：命中闪光（加色、不做深度测试，会盖在怪身上）封顶：最大 1.2 米、0.1 秒，往白里只混三成（亮度只给小而短的东西）
    size = Math.min(size, 1.2);
    dur = Math.min(dur, 0.1);
    const f = flares[flareNext];
    flareNext = (flareNext + 1) % flares.length;
    f.on = true;
    f.t = 0;
    f.dur = dur;
    f.size = size;
    f.mat.color.set(hex).lerp(_c2.set(0xffffff), 0.3);
    f.mat.opacity = 1;
    f.mat.rotation = vrnd() * TAU;
    f.sp.position.set(x, y, z);
    f.sp.scale.setScalar(size * 0.6);
    f.sp.visible = true;
    return f;
  }
  function updateFlares(dt) {
    for (let i = 0; i < flares.length; i++) {
      const f = flares[i];
      if (!f.on) continue;
      f.t += dt;
      const k = f.t / f.dur;
      if (k >= 1) {
        f.on = false;
        f.sp.visible = false;
      } else {
        f.sp.scale.setScalar(f.size * (0.6 + 0.9 * Math.sqrt(k)));
        f.mat.opacity = 1 - k * k;
      }
    }
  }
