  // ---------- 着色器方片特效（预警圈 / 冲击环 / 斩击弧） ----------
  const FX_VERT = 'varying vec2 vP;\nvoid main(){ vP = position.xz; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }';
  const uTime = G.vfx ? G.vfx.U.uTime : { value: 0 }; // 和特效贴图库（js/vfx.js）的着色器共用同一个时间

  // vf-vfx：前面拼上特效贴图库的 GLSL 工具（G.vfx.GLSL，里面声明了 uTime 和噪声贴图）
  const TELE_FRAG = G.vfx.GLSL + '\n' + [
    'uniform vec3 uColor; uniform vec3 uEdge; uniform vec2 uHalf; uniform float uK; uniform float uShape; uniform float uArc; uniform float uIn; uniform float uFill; uniform float uBoss;',
    'varying vec2 vP;',
    'void main(){',
    '  vec2 p = vP * uHalf;',
    '  float d; float g;', // d：到边缘的世界距离（内部为正）；g：0..1 的填充坐标
    '  if (uShape < 0.5) { float l = length(p); d = uHalf.x - l; g = l / uHalf.x; }',
    '  else if (uShape < 1.5) { vec2 q = uHalf - abs(p); d = min(q.x, q.y); g = abs(p.x) / uHalf.x; }',
    // 扇形（熄烛者的拂烛，D5）：局部 +z 是朝向，uArc 是半张角；到两条边的距离按 l·sin(余下的角) 算
    '  else if (uShape < 2.5) { float l = length(p); float a = abs(atan(p.x, p.y)); d = min(uHalf.x - l, l * sin(clamp(uArc - a, -1.5, 1.5))); g = l / uHalf.x; }',
    // 圆环（焰潮，D5）：uIn 是内半径，填充从外圈往里推
    '  else { float l = length(p); d = min(uHalf.x - l, l - uIn); g = (uHalf.x - l) / max(0.01, uHalf.x - uIn); }',
    '  if (d < 0.0) discard;',
    '  float edge = 1.0 - smoothstep(0.1, 0.2, d);', // 外轮廓
    '  float inner = 1.0 - smoothstep(uK - 0.03, uK, g);', // 已经"充满"的部分
    '  float lead = smoothstep(uK - 0.14, uK - 0.02, g) * inner;', // 推进中的前沿亮线
    '  float rim = 1.0 - smoothstep(0.0, 1.1, d);', // 靠边的柔和加深
    '  float hot = smoothstep(0.72, 1.0, uK);',
    '  float pulse = 0.5 + 0.5 * sin(uTime * 16.0);',
    '  float a = 0.24 + rim * 0.16 + inner * (0.24 + 0.2 * uK) + hot * (0.08 + 0.12 * pulse);',
    '  vec3 col = mix(uColor, uEdge, max(edge, lead * 0.75));',
    // vf-vfx：已经充满的部分不再是平涂：按世界坐标铺一层慢慢流动的噪声，分出深浅两档的斑块，再叠一层胞腔边的细纹（往外漂），
    // 只往上加不透明度（任何地面上填充都只会更显眼），外轮廓和推进的前沿亮线不动
    // 低画质不取贴图（预警圈常常铺满半屏，软件渲染下这两次取样最贵），只留原来的平涂
    '  if (uLo < 0.5) {',
    '    vec2 wq = p * 0.17;',
    '    float nf = vfxNA(wq + vec2(uTime * 0.05, -uTime * 0.07)).r;',
    '    float ce = vfxNA(wq * 1.6 + vec2(0.0, uTime * 0.11)).b;',
    '    a += inner * (step(0.56, nf) * 0.1 + ce * 0.07) * (1.0 - edge);',
    '    col = mix(col, uEdge, ce * inner * 0.14 * (1.0 - edge));',
    '  }',
    '  col += hot * pulse * 0.18;',
    // boss-golem：首领的预警圈（uBoss = 1）：填充压到 25–35%（还没推到的部分 4%，推满的部分随时间 18% → 28%，最后一小段轻微闪），
    // 外沿的亮边和深线里面再加一道实色红带（离边 0.34–0.55 米），推进的前沿亮线照旧；形状、半径、时序不变
    // class-d2b2：所有敌方的预警圈都走这一档（小怪的原来是 24–64% 的实心红）；红带的宽度按形状的半宽收（窄的直线 / 十字道不被红带铺满）
    '  if (uBoss > 0.5) {',
    '    float bw = min(0.2, min(uHalf.x, uHalf.y) * 0.16);',
    '    float bBand = smoothstep(0.32, 0.36, d) * (1.0 - smoothstep(0.32 + bw, 0.38 + bw, d));', // 亮边、深线里面再一道实色红带
    '    a = 0.04 + inner * (0.18 + 0.1 * uK) + hot * (0.02 + 0.03 * pulse);',
    '    if (uShape > 0.5 && uShape < 1.5) a *= 0.75;', // class-d2b2：直线 / 十字道又长又常常叠在一起，填充再压一档（推满约 21%）
    '    col = mix(mix(uColor, uEdge, max(edge, lead * 0.75)), uColor, bBand);',
    '    edge = max(edge, bBand * 0.92);',
    '  }',
    '  a *= uFill;', // vf-vfx2：玩家自己放的（友方）预警圈填充减半，外轮廓和前沿亮线不变；敌方的 uFill = 1
    '  a = max(a, max(edge * 0.96, lead * 0.7));',
    // skill-b2：玩家自己的（友方）预警圈只画边：外轮廓 + 一道细的推进线，填充封顶约一成半（原来是半透明的大片浅色实心盘）；敌方 / 首领不走这里
    '  if (uFill < 0.99) { float ld = smoothstep(uK - 0.045, uK - 0.015, g) * inner; a = max(0.03 + rim * 0.05 + inner * 0.06 + hot * pulse * 0.03, max(edge * 0.96, ld * 0.6)); col = mix(uColor, uEdge, max(edge, ld * 0.75)) + hot * pulse * 0.12; }',
    // vf-vfx3：敌方的预警圈在亮边里面再压一道深色线（双层边）：亮边在暗地上显眼、深线在亮特效上显眼，玩家的特效叠上来时轮廓仍是连着的
    '  float dl = step(0.99, uFill) * smoothstep(0.17, 0.21, d) * (1.0 - smoothstep(0.3, 0.34, d));',
    '  col = mix(col, uColor * 0.22, dl);',
    '  a = max(a, dl * 0.92);',
    '  a *= smoothstep(0.0, 0.035, d);',
    '  gl_FragColor = vec4(col, a);',
    '}',
  ].join('\n');

  const foeTeles = [];
  // 点 (x, z) 是否落在某个敌方预警圈里（形状同 game.js 的 insideTelegraph）
  function vsInFoeTele(x, z) {
    for (let i = 0; i < foeTeles.length; i++) {
      const t = foeTeles[i], dx = x - t.x, dz = z - t.z;
      if (t.s === 1) {
        if (Math.abs(dx * t.sn + dz * t.cs) <= t.hz && Math.abs(dx * t.cs - dz * t.sn) <= t.hx) return true;
        continue;
      }
      const l = Math.hypot(dx, dz);
      if (l > t.hx) continue;
      if (t.s === 0) return true;
      if (t.s === 3) { if (l >= t.rin) return true; continue; }
      let da = Math.atan2(dx, dz) - Math.atan2(t.sn, t.cs);
      da = Math.abs(((da + Math.PI) % TAU + TAU) % TAU - Math.PI);
      if (l < 1e-6 || da <= t.arc) return true;
    }
    return false;
  }
  W.foeTeleInfo = () => ({ n: foeTeles.length }); // 测试用（vf-vfx3）
  W.inFoeTele = (x, z) => vsInFoeTele(x, z); // 测试用（vf-vfx3）
  // shape：'circle'（r）/ 'rect'（w、len、ang）/ 'arc' 扇形（r、arc 半张角、ang 朝向）/ 'ring' 圆环（r 外半径、rin 内半径）
  W.makeTelegraph = function (spec, friendly) {
    const rect = spec.shape === 'rect', arc = spec.shape === 'arc', ringS = spec.shape === 'ring';
    const hx = rect ? spec.w / 2 : spec.r, hz = rect ? spec.len / 2 : spec.r;
    const mat = new T.ShaderMaterial({
      uniforms: G.vfx.uni({
        uColor: { value: friendly ? new T.Color(1.0, 0.58, 0.16) : new T.Color(0.96, 0.07, 0.05) },
        uEdge: { value: friendly ? new T.Color(1.0, 0.8, 0.52) : new T.Color(1.0, 0.8, 0.62) }, // skill-b2：友方的边改暖橙（原来近白的淡蓝）
        uHalf: { value: new T.Vector2(hx, hz) },
        uK: { value: 0 },
        uShape: { value: rect ? 1 : arc ? 2 : ringS ? 3 : 0 },
        uArc: { value: arc ? spec.arc : 0 },
        uIn: { value: ringS ? spec.rin : 0 },
        uFill: { value: friendly ? 0.5 : 1 }, // 友方填充减半（vf-vfx2：陨火落下的 0.75 秒里不把落点的怪罩成一片橙）
        // boss-golem：首领的预警圈换成「醒目的红边 + 25–35% 的淡填充，按结算的时间从里往外推满」，地面和玩家的脚看得见；
        // class-d2b2：小怪和没有施放者的敌方预警圈（直线、扇形、十字道）也一样；友方的不变
        uBoss: { value: !friendly ? 1 : 0 },
        uTime,
      }),
      vertexShader: FX_VERT, fragmentShader: TELE_FRAG,
      transparent: true, depthWrite: false, side: T.DoubleSide,
    });
    const mesh = new T.Mesh(gQuad(), mat);
    mesh.position.set(spec.x, 0.08, spec.z);
    mesh.scale.set(hx, 1, hz);
    if (rect || arc) mesh.rotation.y = spec.ang; // 长轴 = 局部 +z = (sin ang, cos ang)
    mesh.renderOrder = 3;
    if (spec.hidden) mesh.visible = false; // 不画（渊式「星雨」自动落下：落点用自己的符环，不铺实心预警圈）
    scene.add(mesh);
    const uK = mat.uniforms.uK;
    // vf-vfx3：登记敌方的预警圈（形状批画玩家的件时，落在里面的压暗，见 vsInFoeTele）
    const reg = friendly || spec.hidden ? null : { s: rect ? 1 : arc ? 2 : ringS ? 3 : 0, x: spec.x, z: spec.z, hx, hz, sn: Math.sin(spec.ang || 0), cs: Math.cos(spec.ang || 0), arc: arc ? spec.arc : 0, rin: ringS ? spec.rin : 0 };
    if (reg) foeTeles.push(reg);
    return {
      mesh, mat, reg,
      setProgress(k) {
        uK.value = k < 0 ? 0 : k > 1 ? 1 : k;
      },
    };
  };
  W.removeTelegraph = function (handle) {
    if (handle.reg) {
      const i = foeTeles.indexOf(handle.reg);
      if (i >= 0) foeTeles.splice(i, 1);
      handle.reg = null;
    }
    scene.remove(handle.mesh);
    retire(handle.mat);
  };

  // 冲击环 / 斩击弧用对象池，稳定后不再分配
  // vf-vfx：冲击环 / 斩击弧拼上特效贴图库的 GLSL 工具（噪声贴图），每个池里的对象一个种子 uSeed
  const RING_FRAG = G.vfx.GLSL + '\n' + [
    'uniform vec3 uColor; uniform vec3 uC0; uniform float uK; uniform float uSeed; varying vec2 vP;',
    'void main(){',
    '  float l = length(vP);',
    '  float rr = 0.12 + 0.88 * (1.0 - (1.0 - uK) * (1.0 - uK));', // 先快后慢地扩张
    // 卡通版：一道硬边的色环，越扩越细；外缘一条浅色亮边；不透明度三档。
    // vf-vfx：环身的粗细沿一圈有起伏（噪声），亮边里有几段更亮的光斑。环始终是连着的一整圈：怪的起手提示、落点预警也用它，不能断
    '  float an = atan(vP.x, vP.y) / 6.2831853;',
    '  float nz = vfxNA(vec2(an * 6.0 + uSeed * 7.0, uSeed + uK * 0.35)).r;',
    '  float w = (0.05 + 0.13 * (1.0 - uK)) * (0.7 + 0.6 * nz);',
    '  if (l > rr || l < rr - w) discard;',
    '  float lit = step(rr - w * 0.35, l);',
    '  float a = uK < 0.45 ? 0.9 : (uK < 0.75 ? 0.62 : 0.32);',
    '  gl_FragColor = vec4(mix(mix(uColor, uC0, lit), vec3(1.0), lit * step(0.72, nz) * 0.35), a);',
    '}',
  ].join('\n');
  // 斩击弧（卡通版）：一弯实色的月牙从弧的一端扫到另一端。前沿最厚、往尾巴收尖，弧的两端也收尖；
  // 径向三道硬边色带（外沿亮芯 uC0 / 主色 uColor / 内沿深色 uC2），不透明度三档。普通混合，不会叠成一片白
  const SLASH_FRAG = G.vfx.GLSL + '\n' + [
    'uniform vec3 uColor; uniform vec3 uC0; uniform vec3 uC2; uniform float uK; uniform float uArc; uniform float uDir; uniform float uIn; uniform float uSeed; varying vec2 vP;',
    'void main(){',
    '  float l = length(vP);',
    '  float an = atan(vP.x, vP.y) / uArc;', // 弧内为 -1..1（vP.y 是局部 +z，即朝向）
    '  if (abs(an) > 1.0 || l > 1.0) discard;',
    '  float h = (an * uDir) * 0.5 + 0.5;', // 0 = 起点，1 = 终点
    '  float d = uK * 2.1 - h;', // 到前沿的距离（> 0 是已经扫过的部分）
    '  if (d < 0.0 || d > 0.7) discard;',
    '  float tail = d / 0.7;',
    '  float ends = min(1.0, min(h, 1.0 - h) * 7.0);',
    '  float thick = (1.0 - uIn) * (1.0 - tail * tail) * ends;',
    '  float s = (l - (1.0 - thick)) / max(thick, 0.001);', // 0 = 内沿，1 = 外沿
    '  if (s < 0.0) discard;',
    // vf-vfx：顺着弧走向的条纹（条纹噪声的快变方向放在径向上）：主色带里几道亮芯色的刀纹，尾巴后半截被条纹撕成一缕缕
    '  float st = vfxNB(vec2(s * 0.9 + uSeed, h * 0.55 + uSeed * 0.3)).r;',
    '  if (tail > 0.45 && st < (tail - 0.45) * 1.2) discard;',
    '  vec3 col = s > 0.74 ? uC0 : (s > 0.34 ? (st > 0.8 ? uC0 : uColor) : uC2);',
    '  float a = uK < 0.42 ? 0.9 : (uK < 0.7 ? 0.62 : 0.32);',
    // phase 3：内沿那一道（暗色带）只留 40% 不透明，月牙压在敌人身上时还看得见敌人；亮芯和主色带不变，形状照样是实色的
    '  if (s <= 0.34) a *= 0.4;',
    '  gl_FragColor = vec4(col, a);',
    '}',
  ].join('\n');

  // blend：缺省加色；卡通的斩击弧 / 冲击环用普通混合（T.NormalBlending），颜色才立得住
  function makePool(frag, extraUniforms, max, blend) {
    return { items: [], frag, extraUniforms, max, blend: blend || T.AdditiveBlending };
  }
  function poolGet(pool) {
    for (let i = 0; i < pool.items.length; i++) if (!pool.items[i].on) return pool.items[i];
    if (pool.items.length >= pool.max) {
      // 池满了就复用进度最靠后的那个
      let o = pool.items[0];
      for (let i = 1; i < pool.items.length; i++) if (pool.items[i].t / pool.items[i].dur > o.t / o.dur) o = pool.items[i];
      return o;
    }
    const uniforms = G.vfx.uni({ uColor: { value: new T.Color() }, uK: { value: 0 } }); // vf-vfx：带上特效贴图库的贴图
    if (pool.extraUniforms) for (const k of pool.extraUniforms) uniforms[k] = { value: k.charAt(1) === 'C' ? new T.Color() : 0 }; // uC0 / uC2：颜色
    const mat = new T.ShaderMaterial({
      uniforms, vertexShader: FX_VERT, fragmentShader: pool.frag,
      transparent: true, depthWrite: false, blending: pool.blend, side: T.DoubleSide,
    });
    const mesh = new T.Mesh(gQuad(), mat);
    mesh.visible = false;
    mesh.renderOrder = 4;
    scene.add(mesh);
    const it = { mesh, u: uniforms, on: false, t: 0, dur: 1 };
    pool.items.push(it);
    return it;
  }
  function poolUpdate(pool, dt) {
    for (let i = 0; i < pool.items.length; i++) {
      const it = pool.items[i];
      if (!it.on) continue;
      it.t += dt;
      if (it.t >= it.dur) {
        it.on = false;
        it.mesh.visible = false;
      } else it.u.uK.value = it.t / it.dur;
    }
  }
  const ringPool = makePool(RING_FRAG, ['uC0', 'uSeed'], 28, T.NormalBlending);
  const slashPool = makePool(SLASH_FRAG, ['uArc', 'uDir', 'uIn', 'uC0', 'uC2', 'uSeed'], 12, T.NormalBlending);

  W.ring = function (x, z, r, hex, dur) {
    // vf-vfx2：冲击环改画进形状批（实心的环，外沿亮带 + 环身，越扩越细；原来每道环各占一次 draw call）。始终是连着的一整圈：怪的起手提示也用它
    if (PF.vShape) {
      const pal = fxPal(hexOf(hex));
      vsBrush(VSH.ring, 2, 1, pal[1], pal[1], 0.3, 0, 1);
      vsEmit(x, 0.1, z, 0, 0, 0, dur || 0.4, r);
      return;
    }
    const it = poolGet(ringPool);
    it.on = true;
    it.t = 0;
    it.dur = dur || 0.4;
    const pal = fxPal(hexOf(hex)); // 卡通版：环身取主色、外缘取亮芯色（伤害类型的代表色映射到色板，其余颜色就地推）
    it.u.uColor.value.set(pal[1]);
    it.u.uC0.value.set(pal[0]);
    it.u.uK.value = 0;
    it.u.uSeed.value = vr(0, 1);
    it.mesh.position.set(x, 0.1, z);
    it.mesh.scale.set(r, 1, r);
    it.mesh.visible = true;
  };

  // opts（可选）：{ dir: 1 | -1 刀光扫过的方向, dur 时长, y 高度, inner 月牙内沿（0 ~ 0.9，越大越细）, tilt 侧倾 / pitch 俯仰（弧度） }
  W.slash = function (x, z, ang, range, arcDeg, hex, opts) {
    const it = poolGet(slashPool), o = opts || {};
    it.on = true;
    it.t = 0;
    it.dur = o.dur || 0.22;
    const pal = fxPal(hexOf(hex));
    it.u.uC0.value.set(pal[0]);
    it.u.uColor.value.set(pal[1]);
    it.u.uC2.value.set(pal[2]);
    it.u.uK.value = 0;
    it.u.uSeed.value = vr(0, 1);
    const half = (arcDeg * Math.PI) / 360;
    it.u.uArc.value = Math.min(Math.PI, half);
    it.u.uDir.value = o.dir === -1 ? -1 : 1;
    it.u.uIn.value = o.inner === undefined ? 0.3 : o.inner;
    it.mesh.position.set(x, o.y === undefined ? 0.95 : o.y, z);
    // tilt：绕朝向轴侧倾（弧度，正 = 局部 +x 一侧抬高；dir = 1 时那一侧是刀光的终点），上挑的一刀不再是平铺在地上的一片；
    // pitch：整片绕自身的横轴俯仰（负 = 弧的中线往上抬）。tilt = π/2 时月牙竖起来，配合 pitch 画从头顶劈到地上的竖劈
    it.mesh.rotation.order = 'YXZ';
    it.mesh.rotation.set(o.pitch || 0, ang, o.tilt || 0);
    it.mesh.scale.set(range, 1, range);
    it.mesh.visible = true;
    // 弧线外沿甩出的几片实色碎片（低画质减半）
    const y = o.y === undefined ? 0.95 : o.y;
    for (let i = 0, n = qualId === 'low' ? 2 : 4; i < n; i++) {
      const a = ang + rand(-half, half) * 0.9, d = range * rand(0.8, 1.0), v = rand(3.5, 6);
      tChunk(0, x + Math.sin(a) * d, y, z + Math.cos(a) * d, Math.sin(a) * v, rand(0.5, 2.5), Math.cos(a) * v, rand(0.16, 0.26), rand(0.12, 0.18), pal[0], pal[1], 6);
    }
  };

  // ----- 闪电：预分配的带状网格 -----
  // vf-vfx：横截面还是原来闪电贴图的「亮芯 + 柔边」，亮芯的宽窄沿着电弧跳动（噪声），柔边里有顺着电弧往前窜的细电丝（条纹噪声），亮芯往白混；加色
  const BOLT_VERT = 'varying vec2 vUv;\nvoid main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }';
  const BOLT_FRAG = G.vfx.GLSL + '\n' + [
    'uniform vec3 uColor; uniform float uOpacity; uniform float uSeed; uniform float uWhite; varying vec2 vUv;',
    'void main(){',
    '  float x = abs(vUv.x - 0.5) * 2.0;', // 0 中线 → 1 边
    '  float prof = x < 0.12 ? 1.0 : (x < 0.4 ? mix(1.0, 0.22, (x - 0.12) / 0.28) : mix(0.22, 0.0, (x - 0.4) / 0.6));',
    '  float w = 0.08 + 0.16 * vfxNA(vec2(vUv.y * 0.31 + uSeed, uTime * 3.7)).r;',
    '  float core = 1.0 - smoothstep(w, w + 0.05, x);',
    '  float fil = smoothstep(0.6, 0.82, vfxNB(vec2(vUv.x * 0.5 + uSeed * 2.0, vUv.y * 0.18 - uTime * 4.0)).r) * (1.0 - smoothstep(0.3, 0.85, x));',
    '  float a = max(max(prof * 0.85, fil * 0.9), core);',
    '  vec3 col = mix(uColor, vec3(1.0), core * uWhite);', // 芯往白混多少（玩家 0.7；vf-vfx3：敌方 0.12）
    '  gl_FragColor = linearToOutputTexel(vec4(col, a * uOpacity));',
    '}',
  ].join('\n');
  const BOLT_MAXP = 220, BOLT_MAXIN = 24, BOLT_LIFE = 0.34;
  const bolts = [];
  // minor：感电放出的小电弧。它们同时最多占 BOLT_MINOR 条，池满时先被顶掉，不会挤掉链雷自己的电弧
  const BOLT_POOL = 12, BOLT_MINOR = 4;
  function boltGet(minor) {
    let free = null, oldMinor = null, oldAny = null, minorN = 0;
    for (let i = 0; i < bolts.length; i++) {
      const b = bolts[i];
      if (!b.on) {
        if (!free) free = b;
        continue;
      }
      if (b.minor) {
        minorN++;
        if (!oldMinor || b.t > oldMinor.t) oldMinor = b;
      }
      if (!oldAny || b.t > oldAny.t) oldAny = b;
    }
    if (minor && minorN >= BOLT_MINOR) return oldMinor;
    if (free) return free;
    if (bolts.length >= BOLT_POOL) return minor ? oldMinor : oldMinor || oldAny; // 池满：先顶掉小电弧，再顶掉最老的
    const g = new T.BufferGeometry();
    const pos = new Float32Array(BOLT_MAXP * 6), uv = new Float32Array(BOLT_MAXP * 4);
    const idx = new Uint16Array((BOLT_MAXP - 1) * 6);
    for (let i = 0; i < BOLT_MAXP - 1; i++) {
      const a = i * 2, o = i * 6;
      idx[o] = a; idx[o + 1] = a + 1; idx[o + 2] = a + 2;
      idx[o + 3] = a + 1; idx[o + 4] = a + 3; idx[o + 5] = a + 2;
    }
    for (let i = 0; i < BOLT_MAXP; i++) {
      uv[i * 4] = 0; uv[i * 4 + 1] = i / 8;
      uv[i * 4 + 2] = 1; uv[i * 4 + 3] = i / 8;
    }
    g.setAttribute('position', new T.BufferAttribute(pos, 3).setUsage(T.DynamicDrawUsage));
    g.setAttribute('uv', new T.BufferAttribute(uv, 2));
    g.setIndex(new T.BufferAttribute(idx, 1));
    // vf-vfx：闪电带换成特效着色器（BOLT_FRAG），所有电弧同一个着色器程序；颜色 / 不透明度走 uniform。
    // 旧的闪电贴图照旧建一次（建贴图会消耗随机数：先后不变，全局随机序列和原来一致）
    boltTex();
    const u = G.vfx.uni({ uColor: { value: new T.Color() }, uOpacity: { value: 1 }, uSeed: { value: 0 }, uWhite: { value: 0.7 } });
    const mat = new T.ShaderMaterial({ uniforms: u, vertexShader: BOLT_VERT, fragmentShader: BOLT_FRAG, transparent: true, blending: T.AdditiveBlending, depthWrite: false, side: T.DoubleSide });
    mat.toneMapped = false;
    const mesh = new T.Mesh(g, mat);
    mesh.frustumCulled = false;
    mesh.visible = false;
    mesh.renderOrder = 5;
    scene.add(mesh);
    const b = { mesh, mat, u, pos, on: false, t: 0, n: 0, inX: new Float32Array(BOLT_MAXIN), inZ: new Float32Array(BOLT_MAXIN), path: new Float32Array(BOLT_MAXP * 2), wid: new Float32Array(BOLT_MAXP), jit: 0, minor: false, hex: 0 };
    bolts.push(b);
    return b;
  }
