        pfPut('tPuff', ckB[j], ckB[j + 1], ckB[j + 2]);
        const ox = camB.x * 0.03, oy = camB.y * 0.03, oz = camB.z * 0.03;
        mBill(x + ox, y + sc * 0.1 + oy, z + oz, sc * 0.62);
