      const x = vsP[j], y = vsP[j + 1], z = vsP[j + 2], sx = vsSx[i] * vc.k * vc.kw, sy = vsSy[i] * vc.k, fd = vc.fd;
      if (md === 0) mStretch(x, y, z, vsD[j], vsD[j + 1], vsD[j + 2], sx, sy);
