      const key = (t) => t.reduce((s, k) => s + pos[k * 3] * cx + pos[k * 3 + 1] * 2 * cy + pos[k * 3 + 2] * cz, 0); // 按口子半径 1、高 2 估
      tris.sort((p, q) => key(p) - key(q));
